import React, { useState, useEffect, useContext } from 'react';
import { AppContext } from '../context/AppContext';
import { useNavigate } from 'react-router-dom';

const OrdersPage = () => {
  const [orders, setOrders] = useState([]);
  const { fetchOrders, loading, user } = useContext(AppContext);
  const navigate = useNavigate();

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    loadOrders();
  }, [user]);

  const loadOrders = async () => {
    const data = await fetchOrders();
    setOrders(data);
  };



  return (
    <div className="max-w-xl mx-auto mt-4 px-4">
      <h1 className="text-lg font-bold mb-3 text-gray-800">My Orders</h1>
      {loading && <p className="text-center">Loading...</p>}
      {orders.length === 0 ? (
        <p className="text-center text-xl text-gray-600 py-8">No orders yet</p>
      ) : (
        <div className="grid gap-4">
          {orders.map(order => {
            const orderDate = new Date(order.orderDate);
            const deliveryDate = new Date(orderDate.getTime() + 7 * 24 * 60 * 60 * 1000);

            return (
              <div key={order._id} className="bg-white p-2 rounded-lg shadow-sm border border-gray-200">
                <div className="flex gap-2">
                  <div className="flex-shrink-0">
                    <img 
                      src={order.bookId?.image} 
                      alt={order.bookId?.title || 'Book'} 
                      className="w-16 h-20 object-cover rounded"
                    />
                  </div>
                  <div className="flex-grow min-w-0">
                    <h3 className="text-sm font-bold truncate">{order.bookId?.title}</h3>
                    <p className="text-xs text-gray-600 truncate">{order.bookId?.author}</p>
                    <p className="text-xs font-bold text-green-600">₹{order.totalAmount}</p>
                    <p className="text-xs text-gray-500">{orderDate.toLocaleDateString()}</p>
                    <p className="text-xs capitalize">{order.status}</p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default OrdersPage;
